templates.content:
name: ${NAME}
services:
  wordpress:
    image: wordpress:latest
    container_name: ${NAME}
    environment:
      WORDPRESS_DB_HOST: ${DB_HOST:-db}
      WORDPRESS_DB_USER: ${DB_USERNAME:-wordpress}
      WORDPRESS_DB_PASSWORD: ${DB_PASSWORD:-changeme}
      WORDPRESS_DB_NAME: ${DB_DATABASE:-wordpress}
      WORDPRESS_CONFIG_EXTRA: |
        /* Handle HTTPS behind reverse proxy */
        if (isset($$_SERVER['HTTP_X_FORWARDED_PROTO']) && $$_SERVER['HTTP_X_FORWARDED_PROTO'] === 'https') {
            $$_SERVER['HTTPS'] = 'on';
        }
    volumes:
      - ./data:/var/www/html
    expose:
      - "80"
    networks:
      - proxy
    restart: unless-stopped

networks:
  proxy:
    external: true

name: ${NAME}
services:
  app:
    image: nextcloud:latest
    container_name: ${NAME}
    restart: unless-stopped
    expose:
      - "80"
    volumes:
      - ./data:/var/www/html/data
      - ./config:/var/www/html/config
      - ./apps:/var/www/html/custom_apps
    environment:
      - MYSQL_HOST=${DB_HOST:-db}
      - MYSQL_DATABASE=${DB_DATABASE:-nextcloud}
      - MYSQL_USER=${DB_USERNAME:-nextcloud}
      - MYSQL_PASSWORD=${DB_PASSWORD:-nextcloud}
      - NEXTCLOUD_ADMIN_USER=${ADMIN_USER:-admin}
      - NEXTCLOUD_ADMIN_PASSWORD=${ADMIN_PASSWORD:-admin}
      - NEXTCLOUD_TRUSTED_DOMAINS=${TRUSTED_DOMAINS:-localhost}
    networks:
      - proxy
      - database

networks:
  proxy:
    external: true
  database:
    external: true

name: ${NAME}
services:
  ghost:
    image: ghost:5-alpine
    container_name: ${NAME}
    environment:
      url: https://${DOMAIN:-localhost}
      database__client: mysql
      database__connection__host: ${DB_HOST:-db}
      database__connection__user: ${DB_USERNAME:-ghost}
      database__connection__password: ${DB_PASSWORD:-changeme}
      database__connection__database: ${DB_DATABASE:-ghost}
    volumes:
      - ./data:/var/lib/ghost/content
    expose:
      - "2368"
    networks:
      - proxy
    restart: unless-stopped

networks:
  proxy:
    external: true
